//! Deterministic localhost v1 transfer over real rbit networking.
//!
//! Owned fixtures only: generated bytes become a real `.torrent` via
//! `TorrentBuilder`, parsed back via `Metainfo::from_bytes`, served over
//! 127.0.0.1 TCP by an rbit `PeerConnection` seeder, and downloaded by a
//! second rbit `PeerConnection` driven by engine leases. Every piece is
//! SHA1-verified against the metainfo before the final bytes are compared to
//! the fixture. No tracker, no DHT, no internet traffic.
//!
//! The metadata-exchange tests start the leecher with the infohash alone:
//! BEP-10 handshake, BEP-9 `ut_metadata` fetch with hostile-input bounds,
//! raw-infohash verification before parsing, then a normal verified transfer.

use std::{
    collections::HashMap,
    sync::{
        Arc, Mutex,
        atomic::{AtomicU64, AtomicUsize, Ordering},
    },
    time::Duration,
};

use bytes::Bytes;
use rbit::{
    Block, BlockRequest, ExtensionHandshake, InfoHash, METADATA_PIECE_SIZE, Message,
    MetadataMessage, MetadataMessageType, Metainfo, PeerConnection, TorrentBuilder, TorrentVersion,
    metadata_piece_count,
};
use sha1::{Digest, Sha1};
use templartorrent_core::{
    model::{JobState, Limits, TorrentId},
    sequence::FileSpec,
};
use templartorrent_engine::{
    event::PeerId,
    peer::{PeerAction, PeerMessage},
    session::{JobSpec, Session},
    worker::{PieceSink, PieceVerifier, SinkError},
};
use templartorrent_rbit_adapter::{matches_request, metadata::fetch_metadata, unpack_bitfield};
use templartorrent_storage::SharedStore;
use tokio::{
    net::{TcpListener, TcpStream},
    time::timeout,
};

const PIECE_LENGTH: u64 = 16_384;
const FILE_A_LEN: usize = 40_000;
const FILE_B_LEN: usize = 10_000;
const BLOCK_CAP: u32 = 16_384;
/// Engine pump iterations; each advances the fake engine clock by 10 ms while
/// socket I/O uses real time. Every test also has a wall-clock deadline.
const MAX_ROUNDS: usize = 5000;
const TEST_DEADLINE: Duration = Duration::from_secs(60);
const SEEDER_PEER_ID: [u8; 20] = [7; 20];
const LEECHER_PEER_ID: [u8; 20] = [9; 20];
const THIRD_PEER_ID: [u8; 20] = [11; 20];
/// BEP-10/BEP-9. Extension 0 is the handshake itself. The two sides advertise
/// deliberately different `ut_metadata` ids so the directional mapping
/// (send with the remote's id) is actually exercised, not assumed.
const EXT_HANDSHAKE_ID: u8 = 0;
const UT_METADATA: &str = "ut_metadata";
const SEEDER_MD_ID: u8 = 7;

fn fixture_bytes(total: usize) -> Vec<u8> {
    // xorshift64star with a fixed seed: deterministic, dependency-free.
    let mut state: u64 = 0x243F_6A88_85A3_08D3;
    let mut out = Vec::with_capacity(total);
    while out.len() < total {
        state ^= state >> 12;
        state ^= state << 25;
        state ^= state >> 27;
        out.extend_from_slice(&state.wrapping_mul(0x2545_F491_4F6C_DD1D).to_le_bytes());
    }
    out.truncate(total);
    out
}

struct Fixture {
    bytes: Vec<u8>,
    raw_info: Vec<u8>,
    info_hash: [u8; 20],
    piece_hashes: Vec<[u8; 20]>,
    files: Vec<(String, u64)>,
}

fn build_fixture() -> Fixture {
    build_fixture_files(&[
        ("a.bin".to_string(), FILE_A_LEN),
        ("b.bin".to_string(), FILE_B_LEN),
    ])
}

fn build_fixture_files(specs: &[(String, usize)]) -> Fixture {
    let total: usize = specs.iter().map(|spec| spec.1).sum();
    let bytes = fixture_bytes(total);
    let mut builder = TorrentBuilder::new("localhost-fixture")
        .version(TorrentVersion::V1)
        .piece_length(PIECE_LENGTH);
    let mut offset = 0;
    for (name, length) in specs {
        builder = builder.add_file(name, bytes[offset..offset + length].to_vec());
        offset += length;
    }
    let torrent_bytes = builder.build().expect("builder accepts owned fixture");
    assert!(
        torrent_bytes.len() <= 16 * 1024 * 1024,
        "fixture torrent exceeds parse bound"
    );
    let metainfo = Metainfo::from_bytes(&torrent_bytes).expect("parse built torrent");
    assert!(
        !metainfo.is_v2() && !metainfo.is_hybrid(),
        "v1 builder must yield a pure-v1 torrent"
    );
    let info_hash = match metainfo.info_hash {
        InfoHash::V1(hash) => hash,
        _ => panic!("v1 builder must yield a v1 infohash"),
    };
    // File layout must match the concatenated fixture stream in offset order.
    let mut files: Vec<(String, u64, u64)> = metainfo
        .info
        .files
        .iter()
        .map(|file| {
            (
                file.path.to_string_lossy().into_owned(),
                file.length,
                file.offset,
            )
        })
        .collect();
    files.sort_by_key(|file| file.2);
    assert_eq!(files.len(), specs.len(), "file count mismatch: {files:?}");
    let mut expected_offset = 0u64;
    for (index, (name, length)) in specs.iter().enumerate() {
        // Multi-file torrents root paths under the torrent name.
        assert_eq!(
            files[index].0,
            format!("localhost-fixture/{name}"),
            "file {index} name mismatch"
        );
        assert_eq!(
            files[index].1, *length as u64,
            "file {index} length mismatch"
        );
        assert_eq!(
            files[index].2, expected_offset,
            "file {index} offset mismatch"
        );
        expected_offset += *length as u64;
    }
    // Independent hash check: sha1 over fixture slices equals metainfo v1 hashes.
    let piece_count = metainfo.info.piece_count();
    assert_eq!(piece_count, total.div_ceil(PIECE_LENGTH as usize));
    let mut piece_hashes = Vec::with_capacity(piece_count);
    for index in 0..piece_count {
        let start = index * PIECE_LENGTH as usize;
        let end = (start + PIECE_LENGTH as usize).min(bytes.len());
        let mut hasher = Sha1::new();
        hasher.update(&bytes[start..end]);
        let expected: [u8; 20] = hasher.finalize().into();
        assert_eq!(
            metainfo.info.get_v1_piece_hash(index),
            Some(expected),
            "piece {index} hash mismatch"
        );
        piece_hashes.push(expected);
    }
    // Independent infohash check: sha1 of the raw info dict equals the parse.
    let raw_info = metainfo.raw_info().to_vec();
    assert!(!raw_info.is_empty(), "raw info dict missing");
    let mut hasher = Sha1::new();
    hasher.update(&raw_info);
    assert_eq!(
        hasher.finalize().as_slice(),
        info_hash,
        "raw info does not hash to the parsed infohash"
    );
    Fixture {
        bytes,
        raw_info,
        info_hash,
        piece_hashes,
        files: files
            .into_iter()
            .map(|(path, length, _)| (path, length))
            .collect(),
    }
}

fn job_spec(fixture: &Fixture) -> JobSpec {
    JobSpec {
        name: "localhost-fixture".into(),
        files: fixture
            .files
            .iter()
            .map(|(path, length)| FileSpec {
                path: path.clone(),
                length: *length,
                wanted: true,
            })
            .collect(),
        piece_length: PIECE_LENGTH,
        max_pieces: 1024,
    }
}

fn piece_len(piece_count: usize, index: u32, total: usize) -> u64 {
    let start = u64::from(index) * PIECE_LENGTH;
    let end = (start + PIECE_LENGTH).min(total as u64);
    assert!(
        (index as usize) < piece_count,
        "piece {index} out of range for {piece_count}"
    );
    end - start
}

type StoredPieces = Arc<Mutex<HashMap<(u64, u32), Vec<u8>>>>;

#[derive(Clone, Default)]
struct SharedSink {
    pieces: StoredPieces,
}

impl PieceSink for SharedSink {
    fn write_piece(
        &mut self,
        torrent: TorrentId,
        piece: u32,
        data: &[u8],
    ) -> Result<(), SinkError> {
        self.pieces
            .lock()
            .unwrap()
            .insert((torrent.0, piece), data.to_vec());
        Ok(())
    }
}

struct Sha1Verifier {
    hashes: Vec<[u8; 20]>,
}

impl PieceVerifier for Sha1Verifier {
    fn verify(&self, piece: u32, data: &[u8]) -> bool {
        let mut hasher = Sha1::new();
        hasher.update(data);
        let digest = hasher.finalize();
        self.hashes
            .get(piece as usize)
            .is_some_and(|expected| expected.as_slice() == digest.as_slice())
    }
}

#[derive(Clone, Copy)]
enum Fault {
    None,
    CorruptOnce { piece: u32 },
    DropAfterBlocks(usize),
}

/// Serve one validated payload request from contiguous fixture bytes.
async fn serve_payload_request(
    conn: &mut PeerConnection,
    fixture: &[u8],
    piece_count: usize,
    index: u32,
    begin: u32,
    length: u32,
    corrupt: bool,
) -> Result<(), String> {
    let id = index as usize;
    if id >= piece_count || length == 0 || length > BLOCK_CAP {
        return Err(format!("bad request {index}:{begin}+{length}"));
    }
    let length_usize = length as usize;
    let begin_usize = begin as usize;
    let expected = piece_len(piece_count, index, fixture.len()) as usize;
    if begin_usize + length_usize > expected {
        return Err(format!("request overruns piece {index}"));
    }
    let start = id * PIECE_LENGTH as usize + begin_usize;
    let mut data = fixture[start..start + length_usize].to_vec();
    if corrupt {
        data[0] ^= 0xFF;
    }
    conn.send(Message::Piece {
        index,
        begin,
        data: Bytes::from(data),
    })
    .await
    .map_err(|error| format!("seed piece: {error}"))?;
    Ok(())
}

/// Serve one accepted connection from contiguous fixture bytes. Returns `Ok`
/// when the leecher disconnects cleanly; any protocol violation fails loudly.
async fn serve_one(
    stream: TcpStream,
    info_hash: [u8; 20],
    peer_id: [u8; 20],
    fixture: &[u8],
    piece_count: usize,
    fault: Fault,
) -> Result<(), String> {
    if !stream
        .peer_addr()
        .map(|addr| addr.ip().is_loopback())
        .unwrap_or(false)
    {
        return Err("seeder accepted a non-loopback connection".into());
    }
    let mut conn = PeerConnection::accept(stream, info_hash, peer_id)
        .await
        .map_err(|error| format!("accept handshake: {error}"))?;
    if !conn.addr.ip().is_loopback() {
        return Err("seeder connection is not loopback".into());
    }
    // Real seeders announce up front; waiting for Interested first could stall.
    let mut wire = vec![0u8; piece_count.div_ceil(8)];
    for piece in 0..piece_count {
        wire[piece / 8] |= 0x80 >> (piece % 8);
    }
    conn.send(Message::Bitfield(Bytes::copy_from_slice(&wire)))
        .await
        .map_err(|error| format!("seed bitfield: {error}"))?;
    conn.send(Message::Unchoke)
        .await
        .map_err(|error| format!("seed unchoke: {error}"))?;
    let mut served = 0usize;
    let mut corrupted = false;
    loop {
        let message = match conn.receive().await {
            Ok(message) => message,
            Err(_) => return Ok(()),
        };
        match message {
            Message::Request {
                index,
                begin,
                length,
            } => {
                if let Fault::DropAfterBlocks(budget) = fault
                    && served >= budget
                {
                    return Ok(());
                }
                let corrupt =
                    matches!(fault, Fault::CorruptOnce { piece } if piece == index) && !corrupted;
                if corrupt {
                    corrupted = true;
                }
                serve_payload_request(
                    &mut conn,
                    fixture,
                    piece_count,
                    index,
                    begin,
                    length,
                    corrupt,
                )
                .await?;
                served += 1;
            }
            Message::Interested
            | Message::NotInterested
            | Message::KeepAlive
            | Message::Have { .. }
            | Message::Cancel { .. } => {}
            other => return Err(format!("unexpected seeder message: {other:?}")),
        }
    }
}

#[derive(Clone, Copy)]
enum MetaFault {
    None,
    CorruptByte,
    Oversize,
    BadTotalSize,
    ZeroExtId,
}

/// Serve extension handshake, `ut_metadata`, bitfield and payload on one
/// connection. Returns the metadata requests served. Replies use the leecher's
/// advertised `ut_metadata` id while requests arrive on ours: the directional
/// mapping is structural here, with deliberately asymmetric ids.
async fn serve_metadata_then_pieces(
    stream: TcpStream,
    info_hash: [u8; 20],
    peer_id: [u8; 20],
    fixture: &[u8],
    raw_info: &[u8],
    piece_count: usize,
    fault: MetaFault,
) -> Result<usize, String> {
    if !stream
        .peer_addr()
        .map(|addr| addr.ip().is_loopback())
        .unwrap_or(false)
    {
        return Err("metadata seeder accepted a non-loopback connection".into());
    }
    let mut conn = PeerConnection::accept(stream, info_hash, peer_id)
        .await
        .map_err(|error| format!("accept handshake: {error}"))?;
    if !conn.addr.ip().is_loopback() {
        return Err("metadata seeder connection is not loopback".into());
    }
    let advertised_id = match fault {
        MetaFault::ZeroExtId => EXT_HANDSHAKE_ID,
        _ => SEEDER_MD_ID,
    };
    let advertised_size = match fault {
        MetaFault::Oversize => 64 * 1024 * 1024,
        _ => raw_info.len() as i64,
    };
    let mut handshake = ExtensionHandshake::with_extensions(&[(UT_METADATA, advertised_id)]);
    handshake.metadata_size = Some(advertised_size);
    conn.send(Message::Extended {
        id: EXT_HANDSHAKE_ID,
        payload: handshake
            .encode()
            .map_err(|error| format!("encode ext handshake: {error}"))?,
    })
    .await
    .map_err(|error| format!("seed ext handshake: {error}"))?;
    let mut wire = vec![0u8; piece_count.div_ceil(8)];
    for piece in 0..piece_count {
        wire[piece / 8] |= 0x80 >> (piece % 8);
    }
    conn.send(Message::Bitfield(Bytes::copy_from_slice(&wire)))
        .await
        .map_err(|error| format!("seed bitfield: {error}"))?;
    conn.send(Message::Unchoke)
        .await
        .map_err(|error| format!("seed unchoke: {error}"))?;
    let mut peer_md: Option<u8> = None;
    let mut md_served = 0usize;
    loop {
        let message = match conn.receive().await {
            Ok(message) => message,
            Err(_) => return Ok(md_served),
        };
        match message {
            Message::Extended { id, payload } if id == EXT_HANDSHAKE_ID => {
                let peer_handshake = ExtensionHandshake::decode(&payload)
                    .map_err(|error| format!("decode peer handshake: {error}"))?;
                peer_md = peer_handshake.get_extension_id(UT_METADATA);
            }
            Message::Extended { id, payload } if id == SEEDER_MD_ID => {
                let request = MetadataMessage::decode(&payload)
                    .map_err(|error| format!("decode metadata request: {error}"))?;
                if request.msg_type != MetadataMessageType::Request {
                    return Err("metadata seeder got a non-request".into());
                }
                let Some(remote) = peer_md else {
                    return Err("metadata request before peer handshake".into());
                };
                let count = metadata_piece_count(raw_info.len());
                if request.piece as usize >= count {
                    let reject = MetadataMessage::reject(request.piece);
                    conn.send(Message::Extended {
                        id: remote,
                        payload: reject
                            .encode()
                            .map_err(|error| format!("encode reject: {error}"))?,
                    })
                    .await
                    .map_err(|error| format!("seed reject: {error}"))?;
                    continue;
                }
                md_served += 1;
                let start = request.piece as usize * METADATA_PIECE_SIZE;
                let end = (start + METADATA_PIECE_SIZE).min(raw_info.len());
                let mut data = raw_info[start..end].to_vec();
                if matches!(fault, MetaFault::CorruptByte) && request.piece == 0 {
                    data[0] ^= 0xFF;
                }
                let total = match fault {
                    MetaFault::BadTotalSize => raw_info.len() as u32 + 1,
                    _ => raw_info.len() as u32,
                };
                let data_message = MetadataMessage::data(request.piece, total, Bytes::from(data));
                conn.send(Message::Extended {
                    id: remote,
                    payload: data_message
                        .encode()
                        .map_err(|error| format!("encode metadata data: {error}"))?,
                })
                .await
                .map_err(|error| format!("seed metadata data: {error}"))?;
            }
            Message::Request {
                index,
                begin,
                length,
            } => {
                serve_payload_request(&mut conn, fixture, piece_count, index, begin, length, false)
                    .await?;
            }
            Message::Interested
            | Message::NotInterested
            | Message::KeepAlive
            | Message::Have { .. }
            | Message::Cancel { .. } => {}
            other => return Err(format!("unexpected metadata seeder message: {other:?}")),
        }
    }
}

enum PumpOutcome {
    Completed {
        requests_per_piece: HashMap<u32, usize>,
        max_budget: usize,
        blamed: Vec<u32>,
    },
    Disconnected,
}

/// Drive one engine peer over a live wire connection: engine outbox becomes
/// wire messages, wire messages become engine events. The engine clock is fake
/// and deterministic; only socket I/O uses real time.
struct Pump<'a> {
    session: &'a mut Session,
    conn: &'a mut PeerConnection,
    torrent: TorrentId,
    peer: PeerId,
    verifier: &'a Sha1Verifier,
    piece_count: usize,
    total: usize,
    allow_disconnect: bool,
}

impl Pump<'_> {
    async fn run(self) -> Result<PumpOutcome, String> {
        let mut now_ns = 0u64;
        let mut outstanding: HashMap<(u32, u32), BlockRequest> = HashMap::new();
        let mut requests_per_piece: HashMap<u32, usize> = HashMap::new();
        let mut blamed = Vec::new();
        let mut max_budget = 0usize;
        for _round in 0..MAX_ROUNDS {
            let report = self.session.update(now_ns, self.verifier);
            if let Some(error) = report.errors.first() {
                return Err(format!("engine error: {error}"));
            }
            blamed.extend(report.blamed.iter().map(|entry| entry.piece));
            for entry in report.outbox {
                let wire = match entry.action {
                    PeerAction::Send(PeerMessage::Request {
                        piece,
                        begin,
                        length,
                    }) => {
                        *requests_per_piece.entry(piece).or_default() += 1;
                        outstanding.insert((piece, begin), BlockRequest::new(piece, begin, length));
                        Message::Request {
                            index: piece,
                            begin,
                            length,
                        }
                    }
                    PeerAction::Send(PeerMessage::Interested) => Message::Interested,
                    PeerAction::Send(PeerMessage::NotInterested) => Message::NotInterested,
                    PeerAction::Send(PeerMessage::Choke) => Message::Choke,
                    PeerAction::Send(PeerMessage::Unchoke) => Message::Unchoke,
                    PeerAction::Send(PeerMessage::Cancel {
                        piece,
                        begin,
                        length,
                    }) => {
                        outstanding.remove(&(piece, begin));
                        Message::Cancel {
                            index: piece,
                            begin,
                            length,
                        }
                    }
                };
                self.conn
                    .send(wire)
                    .await
                    .map_err(|error| format!("leecher send: {error}"))?;
            }
            match timeout(Duration::from_millis(50), self.conn.receive()).await {
                Ok(Ok(message)) => match message {
                    Message::Bitfield(wire) => {
                        let mut words = vec![0u64; self.piece_count.div_ceil(64)];
                        unpack_bitfield(&wire, self.piece_count, &mut words)
                            .map_err(|error| format!("wire bitfield: {error}"))?;
                        self.session
                            .note_bitfield(self.torrent, self.peer, words)
                            .map_err(|error| format!("note bitfield: {error}"))?;
                    }
                    Message::Have { piece } => {
                        self.session
                            .note_have(self.torrent, self.peer, piece)
                            .map_err(|error| format!("note have: {error}"))?;
                    }
                    Message::HaveAll => {
                        let mut words = vec![u64::MAX; self.piece_count.div_ceil(64)];
                        for piece in self.piece_count..words.len() * 64 {
                            words[piece / 64] &= !(1u64 << (piece % 64));
                        }
                        self.session
                            .note_bitfield(self.torrent, self.peer, words)
                            .map_err(|error| format!("note have-all: {error}"))?;
                    }
                    Message::HaveNone => {}
                    Message::Unchoke => {
                        self.session
                            .set_peer_choking(self.torrent, self.peer, false)
                            .map_err(|error| format!("unchoke: {error}"))?;
                    }
                    Message::Choke => {
                        self.session
                            .set_peer_choking(self.torrent, self.peer, true)
                            .map_err(|error| format!("choke: {error}"))?;
                    }
                    Message::Piece { index, begin, data } => {
                        if let Some(request) = outstanding.remove(&(index, begin)) {
                            let block = Block::new(index, begin, data.clone());
                            let actual = piece_len(self.piece_count, index, self.total);
                            if !matches_request(&block, &request, actual) {
                                return Err(format!(
                                    "wire block {index}:{begin} violates its request"
                                ));
                            }
                            self.session
                                .inject_block(self.torrent, self.peer, index, begin, data.to_vec())
                                .map_err(|error| format!("inject block: {error}"))?;
                        }
                    }
                    Message::KeepAlive
                    | Message::Interested
                    | Message::NotInterested
                    | Message::Request { .. }
                    | Message::Cancel { .. }
                    | Message::Port(_)
                    | Message::Suggest { .. }
                    | Message::Reject { .. }
                    | Message::AllowedFast { .. }
                    | Message::Extended { .. } => {}
                    other => return Err(format!("unexpected leecher message: {other:?}")),
                },
                Ok(Err(error)) => {
                    if self.allow_disconnect {
                        let _ = self.session.disconnect(self.torrent, self.peer);
                        return Ok(PumpOutcome::Disconnected);
                    }
                    return Err(format!("wire recv: {error}"));
                }
                Err(_) => {}
            }
            let snapshot = self.session.snapshot();
            max_budget = max_budget.max(snapshot.payload_budget_used);
            now_ns += 10_000_000;
            let row = snapshot
                .jobs
                .iter()
                .find(|row| row.id == self.torrent)
                .ok_or("job vanished mid-transfer")?;
            if row.state == JobState::Seeding {
                return Ok(PumpOutcome::Completed {
                    requests_per_piece,
                    max_budget,
                    blamed,
                });
            }
            if row.state == JobState::Error {
                return Err("job entered Error state".into());
            }
        }
        Err(format!("pump exhausted {MAX_ROUNDS} rounds"))
    }
}

fn new_session(sink: SharedSink) -> Session {
    new_session_with_sink(Box::new(sink))
}

fn new_session_with_sink(sink: Box<dyn PieceSink>) -> Session {
    Session::new(Limits::default(), vec![sink], 16, 0).expect("session")
}

async fn run_leecher(
    addr: std::net::SocketAddr,
    fixture: &Fixture,
    session: &mut Session,
    id: TorrentId,
    verifier: &Sha1Verifier,
    peer_id: [u8; 20],
    allow_disconnect: bool,
) -> Result<(PumpOutcome, PeerConnection), String> {
    let mut conn = PeerConnection::connect(addr, fixture.info_hash, peer_id)
        .await
        .map_err(|error| format!("connect: {error}"))?;
    if !conn.addr.ip().is_loopback() {
        return Err("leecher connection is not loopback".into());
    }
    let peer = session
        .connect(id)
        .map_err(|error| format!("engine connect: {error}"))?;
    let outcome = Pump {
        session,
        conn: &mut conn,
        torrent: id,
        peer,
        verifier,
        piece_count: fixture.piece_hashes.len(),
        total: fixture.bytes.len(),
        allow_disconnect,
    }
    .run()
    .await?;
    Ok((outcome, conn))
}

fn stored_bytes(sink: &SharedSink, id: TorrentId, piece_count: usize) -> Vec<u8> {
    let stored = sink.pieces.lock().unwrap();
    let mut actual = Vec::new();
    for piece in 0..piece_count as u32 {
        actual.extend_from_slice(
            stored
                .get(&(id.0, piece))
                .unwrap_or_else(|| panic!("piece {piece} missing from sink")),
        );
    }
    actual
}

async fn accept_and_serve(
    listener: TcpListener,
    info_hash: [u8; 20],
    peer_id: [u8; 20],
    fixture: Vec<u8>,
    piece_count: usize,
    faults: Vec<Fault>,
) -> Result<(), String> {
    for fault in faults {
        let (stream, _) = listener
            .accept()
            .await
            .map_err(|error| format!("accept: {error}"))?;
        serve_one(stream, info_hash, peer_id, &fixture, piece_count, fault).await?;
    }
    Ok(())
}

async fn bind_loopback() -> TcpListener {
    let listener = TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind loopback");
    assert!(
        listener.local_addr().unwrap().ip().is_loopback(),
        "listener is not loopback"
    );
    listener
}

#[tokio::test]
async fn localhost_transfer_completes_with_verified_bytes() {
    timeout(TEST_DEADLINE, async {
        let fixture = build_fixture();
        let listener = bind_loopback().await;
        let addr = listener.local_addr().unwrap();
        let seed = tokio::spawn(accept_and_serve(
            listener,
            fixture.info_hash,
            SEEDER_PEER_ID,
            fixture.bytes.clone(),
            fixture.piece_hashes.len(),
            vec![Fault::None],
        ));

        let sink = SharedSink::default();
        let mut session = new_session(sink.clone());
        let id = session.add(job_spec(&fixture)).unwrap();
        let verifier = Sha1Verifier {
            hashes: fixture.piece_hashes.clone(),
        };
        let (outcome, conn) = run_leecher(
            addr,
            &fixture,
            &mut session,
            id,
            &verifier,
            LEECHER_PEER_ID,
            false,
        )
        .await
        .expect("transfer pump");
        let PumpOutcome::Completed {
            max_budget, blamed, ..
        } = outcome
        else {
            panic!("unexpected disconnect on a clean transfer");
        };
        assert!(blamed.is_empty(), "clean transfer blamed: {blamed:?}");
        assert!(
            max_budget <= 65_536,
            "payload budget peaked at {max_budget} bytes"
        );
        assert_eq!(session.snapshot().payload_budget_used, 0);
        assert_eq!(
            stored_bytes(&sink, id, fixture.piece_hashes.len()),
            fixture.bytes,
            "final bytes differ from the owned fixture"
        );
        drop(conn);
        seed.await.unwrap().expect("seeder clean");
    })
    .await
    .expect("transfer exceeded its deadline");
}

#[tokio::test]
async fn seed_serves_verified_bytes_to_third_peer() {
    timeout(TEST_DEADLINE, async {
        let fixture = build_fixture();
        // Phase 1: first leecher completes from the original seeder.
        let listener = bind_loopback().await;
        let addr = listener.local_addr().unwrap();
        let seed = tokio::spawn(accept_and_serve(
            listener,
            fixture.info_hash,
            SEEDER_PEER_ID,
            fixture.bytes.clone(),
            fixture.piece_hashes.len(),
            vec![Fault::None],
        ));
        let sink_one = SharedSink::default();
        let mut session_one = new_session(sink_one.clone());
        let id_one = session_one.add(job_spec(&fixture)).unwrap();
        let verifier = Sha1Verifier {
            hashes: fixture.piece_hashes.clone(),
        };
        let (outcome, conn) = run_leecher(
            addr,
            &fixture,
            &mut session_one,
            id_one,
            &verifier,
            LEECHER_PEER_ID,
            false,
        )
        .await
        .expect("first transfer");
        assert!(matches!(outcome, PumpOutcome::Completed { .. }));
        drop(conn);
        seed.await.unwrap().expect("original seeder clean");
        assert_eq!(session_one.snapshot().jobs[0].state, JobState::Seeding);

        // Phase 2: the completed leecher seeds a third peer from its sink,
        // which holds only hash-verified bytes by construction.
        let served = stored_bytes(&sink_one, id_one, fixture.piece_hashes.len());
        assert_eq!(served, fixture.bytes);
        let listener_two = bind_loopback().await;
        let addr_two = listener_two.local_addr().unwrap();
        let reseed = tokio::spawn(accept_and_serve(
            listener_two,
            fixture.info_hash,
            LEECHER_PEER_ID,
            served,
            fixture.piece_hashes.len(),
            vec![Fault::None],
        ));
        let sink_two = SharedSink::default();
        let mut session_two = new_session(sink_two.clone());
        let id_two = session_two.add(job_spec(&fixture)).unwrap();
        let (outcome, conn_two) = run_leecher(
            addr_two,
            &fixture,
            &mut session_two,
            id_two,
            &verifier,
            THIRD_PEER_ID,
            false,
        )
        .await
        .expect("seeded transfer");
        assert!(matches!(outcome, PumpOutcome::Completed { .. }));
        assert_eq!(
            stored_bytes(&sink_two, id_two, fixture.piece_hashes.len()),
            fixture.bytes,
            "third peer bytes differ from the fixture"
        );
        drop(conn_two);
        reseed.await.unwrap().expect("reseed clean");
    })
    .await
    .expect("seed path exceeded its deadline");
}

