#[tokio::test]
async fn metadata_exchange_rejects_zero_extension_id() {
    timeout(TEST_DEADLINE, async {
        let fixture = build_fixture();
        let (addr, seed) = spawn_metadata_seeder(&fixture, MetaFault::ZeroExtId).await;
        let mut conn = connect_infohash(addr, fixture.info_hash).await;
        let error = fetch_metadata(&mut conn, fixture.info_hash)
            .await
            .unwrap_err();
        // decode drops id-0 entries, so a 0-advertisement reads as absent;
        // either way nothing is ever sent to extension id 0.
        assert!(
            error.contains("hides ut_metadata") || error.contains("extension id 0"),
            "wrong rejection for id-0 advertisement: {error}"
        );
        drop(conn);
        let md_served = seed.await.unwrap().expect("seeder clean");
        assert_eq!(md_served, 0, "no request sent to extension id 0");
    })
    .await
    .expect("zero-id run exceeded its deadline");
}

/// Owned temp root, removed on scope exit. Declare before any store so file
/// handles close first, which Windows requires for removal.
struct TempRoot(std::path::PathBuf);

impl TempRoot {
    fn new(tag: &str) -> Self {
        static NEXT: AtomicU64 = AtomicU64::new(0);
        let id = NEXT.fetch_add(1, Ordering::SeqCst);
        let mut dir = std::env::temp_dir();
        dir.push(format!(
            "templartorrent-localhost-{tag}-{}-{id}",
            std::process::id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        Self(dir)
    }

    fn path(&self) -> &std::path::Path {
        &self.0
    }
}

impl Drop for TempRoot {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

struct CountingStore<S> {
    inner: S,
    writes: Arc<AtomicUsize>,
}

impl<S: PieceSink> PieceSink for CountingStore<S> {
    fn write_piece(
        &mut self,
        torrent: TorrentId,
        piece: u32,
        data: &[u8],
    ) -> Result<(), SinkError> {
        self.writes.fetch_add(1, Ordering::SeqCst);
        self.inner.write_piece(torrent, piece, data)
    }
}

fn job_files(fixture: &Fixture) -> Vec<(Vec<String>, u64)> {
    fixture
        .files
        .iter()
        .map(|(path, length)| (path.split('/').map(str::to_string).collect(), *length))
        .collect()
}

#[tokio::test]
async fn file_backed_transfer_writes_verified_files() {
    timeout(TEST_DEADLINE, async {
        let temp = TempRoot::new("transfer");
        let fixture = build_fixture();
        let listener = bind_loopback().await;
        let addr = listener.local_addr().unwrap();
        let seed = tokio::spawn(accept_and_serve(
            listener,
            fixture.info_hash,
            SEEDER_PEER_ID,
            fixture.bytes.clone(),
            fixture.piece_hashes.len(),
            vec![Fault::None],
        ));

        let store = SharedStore::new();
        let writes = Arc::new(AtomicUsize::new(0));
        let counting = CountingStore {
            inner: store.clone(),
            writes: Arc::clone(&writes),
        };
        let mut session = new_session_with_sink(Box::new(counting));
        let id = session.add(job_spec(&fixture)).unwrap();
        store
            .add_job(id, temp.path(), &job_files(&fixture), PIECE_LENGTH)
            .unwrap();
        let verifier = Sha1Verifier {
            hashes: fixture.piece_hashes.clone(),
        };
        let (outcome, conn) = run_leecher(
            addr,
            &fixture,
            &mut session,
            id,
            &verifier,
            LEECHER_PEER_ID,
            false,
        )
        .await
        .expect("file-backed pump");
        assert!(matches!(outcome, PumpOutcome::Completed { .. }));
        assert_eq!(
            writes.load(Ordering::SeqCst),
            fixture.piece_hashes.len(),
            "each verified piece written exactly once"
        );
        let mut on_disk = Vec::new();
        for (path, _) in &fixture.files {
            on_disk.extend_from_slice(&std::fs::read(temp.path().join(path)).unwrap());
        }
        assert_eq!(on_disk, fixture.bytes, "on-disk bytes differ from fixture");
        drop(conn);
        drop(session);
        drop(store);
        seed.await.unwrap().expect("seeder clean");
    })
    .await
    .expect("file-backed transfer exceeded its deadline");
}

#[tokio::test]
async fn file_backed_resume_adopts_without_rewrite() {
    timeout(TEST_DEADLINE, async {
        let temp = TempRoot::new("resume");
        let fixture = build_fixture();
        // Pre-existing complete files, written without touching the engine.
        for (path, length) in &fixture.files {
            let full = temp.path().join(path);
            std::fs::create_dir_all(full.parent().unwrap()).unwrap();
            let offset: usize = fixture
                .files
                .iter()
                .take_while(|(candidate, _)| candidate != path)
                .map(|(_, size)| *size as usize)
                .sum();
            std::fs::write(&full, &fixture.bytes[offset..offset + *length as usize]).unwrap();
        }

        let store = SharedStore::new();
        let writes = Arc::new(AtomicUsize::new(0));
        let counting = CountingStore {
            inner: store.clone(),
            writes: Arc::clone(&writes),
        };
        let mut session = new_session_with_sink(Box::new(counting));
        let id = session.add(job_spec(&fixture)).unwrap();
        store
            .add_job(id, temp.path(), &job_files(&fixture), PIECE_LENGTH)
            .unwrap();
        // Real piece hashes: adoption proves content match, not just presence.
        let verifier = Sha1Verifier {
            hashes: fixture.piece_hashes.clone(),
        };
        let report = session.recheck(id, &store, &verifier).unwrap();
        assert_eq!(report.verified, fixture.piece_hashes.len());
        assert_eq!(writes.load(Ordering::SeqCst), 0, "resume rewrote files");
        assert_eq!(session.snapshot().jobs[0].state, JobState::Seeding);
        let mut on_disk = Vec::new();
        for (path, _) in &fixture.files {
            on_disk.extend_from_slice(&std::fs::read(temp.path().join(path)).unwrap());
        }
        assert_eq!(on_disk, fixture.bytes, "resume altered on-disk bytes");
    })
    .await
    .expect("file-backed resume exceeded its deadline");
}
